CREATE TABLE accounts (id TEXT PRIMARY KEY, handle TEXT NOT NULL UNIQUE, created_at BIGINT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE members (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), name TEXT NOT NULL, created_at BIGINT NOT NULL, payload TEXT NOT NULL, UNIQUE(account_id,name), UNIQUE(account_id,id));
CREATE TABLE credentials (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), member_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('device','token')), name TEXT NOT NULL, secret_hash TEXT NOT NULL UNIQUE, created_at BIGINT NOT NULL, expires_at BIGINT, revoked_at BIGINT, last_used_at BIGINT, payload TEXT NOT NULL, FOREIGN KEY(account_id,member_id) REFERENCES members(account_id,id));
CREATE UNIQUE INDEX live_token_names ON credentials(account_id,name) WHERE kind = 'token' AND revoked_at IS NULL;
CREATE TABLE device_codes (device_code_hash TEXT PRIMARY KEY, user_code TEXT NOT NULL UNIQUE, expires_at BIGINT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE machines (account_id TEXT NOT NULL REFERENCES accounts(id), name TEXT NOT NULL, token_id TEXT NOT NULL, actor_id TEXT NOT NULL, user_id TEXT NOT NULL, kind TEXT NOT NULL, created_at BIGINT NOT NULL, last_seen BIGINT, payload TEXT NOT NULL, PRIMARY KEY(account_id,name));
CREATE TABLE machine_tombstones (account_id TEXT NOT NULL REFERENCES accounts(id), name TEXT NOT NULL, at BIGINT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(account_id,name));
CREATE TABLE endpoints (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, machine TEXT NOT NULL, handle TEXT NOT NULL, kind TEXT NOT NULL, token_hash TEXT, created_at BIGINT NOT NULL, last_seen BIGINT, payload TEXT NOT NULL, PRIMARY KEY(account_id,id), UNIQUE(account_id,machine,handle), UNIQUE(account_id,token_hash));
CREATE TABLE messages (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, thread TEXT NOT NULL, reply_to TEXT, kind TEXT NOT NULL, from_ep TEXT NOT NULL, to_addr TEXT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(account_id,id));
CREATE INDEX messages_thread ON messages(account_id,thread);
CREATE INDEX messages_expiry ON messages(account_id,expires_at);
CREATE TABLE deliveries (seq INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL, message_id TEXT NOT NULL, endpoint TEXT NOT NULL, expires_at BIGINT NOT NULL, acked_at BIGINT, rejected_at BIGINT, rejection TEXT, state TEXT NOT NULL, FOREIGN KEY(account_id,message_id) REFERENCES messages(account_id,id) ON DELETE CASCADE);
CREATE INDEX deliveries_inbox ON deliveries(account_id,endpoint,seq);
CREATE TABLE idempotency (account_id TEXT NOT NULL REFERENCES accounts(id), from_ep TEXT NOT NULL, client_id TEXT NOT NULL, created_at BIGINT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(account_id,from_ep,client_id));
CREATE TABLE hub_state (account_id TEXT NOT NULL REFERENCES accounts(id), key TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(account_id,key));
CREATE TABLE pair_events (account_id TEXT NOT NULL REFERENCES accounts(id), from_ep TEXT NOT NULL, to_ep TEXT NOT NULL, at BIGINT NOT NULL);
CREATE INDEX pair_events_pair ON pair_events(account_id,from_ep,to_ep,at);
CREATE TABLE local_events (account_id TEXT NOT NULL REFERENCES accounts(id), from_ep TEXT NOT NULL, to_ep TEXT NOT NULL, at BIGINT NOT NULL);
CREATE INDEX local_events_pair ON local_events(account_id,from_ep,to_ep,at);
CREATE TABLE activity (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL REFERENCES accounts(id), at BIGINT NOT NULL, kind TEXT NOT NULL, endpoint TEXT, reference TEXT, detail TEXT NOT NULL);
CREATE INDEX activity_at ON activity(account_id,at);
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL REFERENCES accounts(id), at BIGINT NOT NULL, kind TEXT NOT NULL, endpoint TEXT, reference TEXT, detail TEXT NOT NULL);
CREATE INDEX audit_at ON audit(account_id,at);
